//! Wire shapes of the UI's daemon methods and HTTP API.
//!
//! These structs are the single source for `ui/src/lib/api/types/`
//! (generated by ts-rs; see `types_are_current` below). Responses use
//! `deny_unknown_fields` on decode so the contract tests catch drift in
//! either direction.

use serde::{Deserialize, Serialize};
use ts_rs::TS;

// ── graph_snapshot ─────────────────────────────────────────────────────

#[derive(Debug, Clone, Default, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct GraphSnapshotParams {
    #[serde(default)]
    pub namespace: Option<String>,
    #[serde(default)]
    pub edge_offset: usize,
    #[serde(default)]
    pub edge_limit: Option<usize>,
}

/// Column-oriented graph. Numeric columns are base64 little-endian typed
/// arrays: `u32` for `ns`, `degree`, `src`, `dst`; `u8` for `phase`,
/// `permastore`, `type`; `f32` for `strength`, `decayStrength`, `stability`,
/// `weight`; `f64` (millis) for `createdAt`, `lastAccess`.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct GraphSnapshot {
    pub generated_at: i64,
    pub namespaces: Vec<NamespaceRef>,
    pub node_count: usize,
    /// Present on the first page (`edgeOffset == 0`) only.
    pub nodes: Option<SnapshotNodes>,
    pub edges: SnapshotEdges,
    pub edge_total: usize,
    pub edge_offset: usize,
    pub next_edge_offset: Option<usize>,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct NamespaceRef {
    pub id: u32,
    pub name: String,
    /// R thresholds for Full → Summary, Summary → Ghost, Ghost → deletion.
    pub thresholds: [f32; 3],
    /// Stability (days) at which a memory enters permastore.
    pub permastore_days: f32,
    /// Effective decay rate multiplier (namespace override or global).
    pub decay_multiplier: f32,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct SnapshotNodes {
    pub ids: Vec<String>,
    pub ns: String,
    pub phase: String,
    pub strength: String,
    pub decay_strength: String,
    pub stability: String,
    pub created_at: String,
    pub last_access: String,
    pub degree: String,
    pub permastore: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(deny_unknown_fields)]
pub struct SnapshotEdges {
    pub src: String,
    pub dst: String,
    #[serde(rename = "type")]
    #[ts(rename = "type")]
    pub kind: String,
    pub weight: String,
}

// ── system_status ──────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct SystemStatus {
    pub version: String,
    pub protocol_version: u32,
    pub pid: u32,
    pub started_at: i64,
    pub uptime_secs: u64,
    pub data_dir: String,
    pub socket: String,
    pub health: crate::mcp::bridge::HealthStatus,
    pub cache: CacheStatus,
    pub embedding: EmbeddingStatus,
    pub process: ProcessStatus,
    pub clients: Vec<ClientInfo>,
    pub sweep: SweepStatus,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct CacheStatus {
    pub hits: u64,
    pub misses: u64,
    pub entries: u64,
    pub used_bytes: u64,
    pub budget_bytes: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct EmbeddingStatus {
    pub provider: String,
    pub model: String,
    pub dimensions: usize,
    /// `null` until this daemon has made an embedding request.
    pub latency_ms: Option<LatencyMs>,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(deny_unknown_fields)]
pub struct LatencyMs {
    pub last: f64,
    pub smoothed: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ProcessStatus {
    pub rss_bytes: Option<u64>,
    /// Percent of one core since the previous `system_status` (or since start).
    pub cpu_percent: Option<f64>,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ClientInfo {
    pub id: u64,
    /// Name from MCP `clientInfo`, or `null` when the client never said.
    pub agent: Option<String>,
    /// `"mcp"`, `"ui"`, or `"unknown"`.
    pub kind: String,
    pub since: i64,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct SweepStatus {
    pub enabled: bool,
    pub interval_secs: u64,
    pub last_at: Option<i64>,
    pub next_at: Option<i64>,
}

// ── hello / subscribe ──────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct HelloParams {
    pub agent: Option<String>,
    #[serde(default)]
    pub kind: Option<String>,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct SubscribeParams {
    /// Event kinds to receive; empty or absent means all.
    #[serde(default)]
    pub kinds: Vec<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Subscribed {
    pub subscribed: Vec<String>,
}

// ── HTTP-only shapes ───────────────────────────────────────────────────

/// `GET /api/ui/session`: what the shell needs before anything else.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct UiSession {
    /// The UI (and recalld) version; they are always the same binary.
    pub version: String,
    pub daemon: DaemonState,
    pub socket: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct DaemonState {
    /// `"connected"`, `"unavailable"` or `"unsupported"` (no UI methods).
    pub status: String,
    pub message: Option<String>,
}

/// Error body of every non-2xx `/api/ui/*` response.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct UiError {
    /// Stable machine code: `forbidden`, `notFound`, `invalidInput`,
    /// `daemonUnavailable`, `unsupported`, `internal`.
    pub error: String,
    pub message: String,
}

/// Every type the frontend imports, in declaration order.
#[cfg(test)]
pub(crate) fn declarations() -> String {
    use crate::ui::events;
    let cfg = ts_rs::Config::new().with_large_int("number");
    macro_rules! decls {
        ($($t:ty),* $(,)?) => {{
            let mut out = String::new();
            $( out.push_str("export "); out.push_str(&<$t as TS>::decl(&cfg)); out.push_str("\n\n"); )*
            out
        }};
    }
    let mut out = String::from(
        "// Generated by `cargo test --features ui ui::wire` from src/ui/wire.rs and the\n\
         // Rust response types it references. Do not edit; run\n\
         // `UPDATE_UI_TYPES=1 cargo test --features ui types_are_current` instead.\n\n",
    );
    out.push_str(&decls!(
        GraphSnapshotParams,
        GraphSnapshot,
        NamespaceRef,
        SnapshotNodes,
        SnapshotEdges,
        SystemStatus,
        CacheStatus,
        EmbeddingStatus,
        LatencyMs,
        ProcessStatus,
        ClientInfo,
        SweepStatus,
        HelloParams,
        SubscribeParams,
        Subscribed,
        UiSession,
        DaemonState,
        UiError,
        events::UiEvent,
        events::RecallEvent,
        events::Seed,
        events::TraceStep,
        events::StoreEvent,
        events::LinkEvent,
        events::ReinforceEvent,
        events::ForgetEvent,
        events::PhaseChangeEvent,
        events::SweepEvent,
        events::SweepMoved,
        events::LaggedEvent,
        crate::mcp::bridge::HealthStatus,
        crate::mcp::bridge::SubsystemHealth,
        crate::mcp::bridge::NamespaceInfo,
        crate::mcp::bridge::NamespaceStats,
        crate::mcp::bridge::PhaseCounts,
        crate::api::models::HealthReport,
        crate::api::models::HealthOverview,
        crate::api::models::PhaseCounts,
        crate::api::models::DecayForecast,
        crate::api::models::TransitionCounts,
        crate::api::models::AtRiskMemory,
        crate::api::models::AgeDistribution,
        crate::api::models::StorageBreakdown,
        crate::api::models::VectorFileSize,
        crate::api::models::MetadataStats,
        crate::api::models::TagCount,
    ));
    out
}

#[cfg(test)]
mod tests {
    /// CI fails here when a Rust response struct changed but the generated
    /// TypeScript types were not regenerated.
    #[test]
    fn types_are_current() {
        let path =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("ui/src/lib/api/types/index.ts");
        let expected = super::declarations();
        if std::env::var_os("UPDATE_UI_TYPES").is_some() {
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(&path, &expected).unwrap();
            return;
        }
        let actual = std::fs::read_to_string(&path).unwrap_or_default();
        assert!(
            actual == expected,
            "ui/src/lib/api/types/index.ts is stale; run \
             `UPDATE_UI_TYPES=1 cargo test --features ui types_are_current`"
        );
    }
}
